import React, { useCallback, useEffect, useMemo, useState } from "react";
import { toast } from "react-toastify";
import {
  FiCheck,
  FiEdit2,
  FiImage,
  FiPlus,
  FiRefreshCw,
  FiSearch,
  FiTrash2,
  FiUploadCloud,
  FiX,
} from "react-icons/fi";

import api, { getApiErrorMessage } from "../../services/api";
import { useLanguage } from "../../contexts/LanguageContext";

const API_BASE_URL =
  process.env.REACT_APP_API_URL || "http://127.0.0.1:8000";

const INITIAL_IMAGE_FORM = {
  title_en: "",
  title_km: "",
  description_en: "",
  description_km: "",
  image: "",
  order: 0,
  is_active: true,
};

const AdminCharity = () => {
  const { t, language } = useLanguage();
  const isKhmer = language === "km" || language === "kh";
  const suffix = isKhmer ? "km" : "en";

  const [images, setImages] = useState([]);
  const [imageForm, setImageForm] = useState(INITIAL_IMAGE_FORM);

  const [loadingImages, setLoadingImages] = useState(true);
  const [savingImage, setSavingImage] = useState(false);
  const [uploadingImage, setUploadingImage] = useState(false);
  const [deletingId, setDeletingId] = useState(null);

  const [showImageForm, setShowImageForm] = useState(false);
  const [editingImageId, setEditingImageId] = useState(null);
  const [search, setSearch] = useState("");

  const tr = (key, english, khmer) => {
    const translated = typeof t === "function" ? t(key) : "";

    if (
      translated &&
      translated !== key &&
      !String(translated).includes("undefined")
    ) {
      return translated;
    }

    return isKhmer ? khmer : english;
  };

  const localized = (item, field, fallback = "") => {
    const selected = item?.[`${field}_${suffix}`];

    if (
      selected !== undefined &&
      selected !== null &&
      String(selected).trim() !== ""
    ) {
      return selected;
    }

    return fallback;
  };

  const getImageUrl = (path) => {
    if (!path) return "";

    const value = String(path);

    if (
      value.startsWith("http://") ||
      value.startsWith("https://") ||
      value.startsWith("blob:")
    ) {
      return value;
    }

    return value.startsWith("/")
      ? `${API_BASE_URL}${value}`
      : `${API_BASE_URL}/${value}`;
  };

  const apiError = (error, fallback) => {
    if (typeof getApiErrorMessage === "function") {
      return getApiErrorMessage(error, fallback);
    }

    const detail = error?.response?.data?.detail;

    if (typeof detail === "string") return detail;

    if (Array.isArray(detail)) {
      return detail
        .map((item) => item?.msg || item)
        .filter(Boolean)
        .join(", ");
    }

    return error?.response?.data?.message || error?.message || fallback;
  };


  const fetchImages = useCallback(async () => {
    try {
      setLoadingImages(true);

      const response = await api.get("/api/charity/images/admin/all", {
        params: {
          skip: 0,
          limit: 200,
        },
      });

      const data = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.items)
        ? response.data.items
        : [];

      setImages(data);
    } catch (error) {
      console.error("Fetch charity images error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.imagesLoadFailed",
            "Failed to load charity images.",
            "មិនអាចទាញយករូបភាពសប្បុរសធម៌បានទេ។"
          )
        )
      );

      setImages([]);
    } finally {
      setLoadingImages(false);
    }
  }, []);

  useEffect(() => {
    fetchImages();
  }, [fetchImages]);

  const filteredImages = useMemo(() => {
    const keyword = search.trim().toLowerCase();

    if (!keyword) return images;

    return images.filter((item) =>
      [
        item.title_en,
        item.title_km,
        item.description_en,
        item.description_km,
        item.order,
      ]
        .filter((value) => value !== null && value !== undefined)
        .join(" ")
        .toLowerCase()
        .includes(keyword)
    );
  }, [images, search]);


  const handleImageFormChange = (event) => {
    const { name, value, type, checked } = event.target;

    setImageForm((current) => ({
      ...current,
      [name]: type === "checkbox" ? checked : value,
    }));
  };


  const resetImageForm = () => {
    setImageForm(INITIAL_IMAGE_FORM);
    setEditingImageId(null);
    setShowImageForm(false);
  };

  const openCreateImage = () => {
    setImageForm(INITIAL_IMAGE_FORM);
    setEditingImageId(null);
    setShowImageForm(true);
  };

  const openEditImage = (item) => {
    setImageForm({
      title_en: item.title_en || "",
      title_km: item.title_km || "",
      description_en: item.description_en || "",
      description_km: item.description_km || "",
      image: item.image || "",
      order:
        item.order !== undefined && item.order !== null
          ? Number(item.order)
          : 0,
      is_active:
        item.is_active === undefined ? true : Boolean(item.is_active),
    });

    setEditingImageId(item.id);
    setShowImageForm(true);

    window.scrollTo({
      top: 0,
      behavior: "smooth",
    });
  };

  const uploadImageFile = async (event) => {
    const file = event.target.files?.[0];

    if (!file) return;

    const allowedTypes = ["image/jpeg", "image/png", "image/webp"];

    if (!allowedTypes.includes(file.type)) {
      toast.error(
        tr(
          "charity.invalidImage",
          "Only JPG, PNG and WEBP images are allowed.",
          "អនុញ្ញាតតែរូបភាព JPG, PNG និង WEBP ប៉ុណ្ណោះ។"
        )
      );
      event.target.value = "";
      return;
    }

    if (file.size > 5 * 1024 * 1024) {
      toast.error(
        tr(
          "charity.imageTooLarge",
          "Image size must not exceed 5 MB.",
          "ទំហំរូបភាពមិនត្រូវលើសពី 5MB។"
        )
      );
      event.target.value = "";
      return;
    }

    const formData = new FormData();
    formData.append("file", file);

    try {
      setUploadingImage(true);

      const response = await api.post(
        "/api/charity/images/upload",
        formData
      );

      const imagePath = response.data?.path || response.data?.url;

      if (!imagePath) {
        throw new Error("Backend did not return image path.");
      }

      setImageForm((current) => ({
        ...current,
        image: imagePath,
      }));

      toast.success(
        tr(
          "charity.imageUploaded",
          "Image uploaded successfully.",
          "បាន Upload រូបភាពដោយជោគជ័យ។"
        )
      );
    } catch (error) {
      console.error("Upload charity image error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.uploadFailed",
            "Failed to upload image.",
            "មិនអាច Upload រូបភាពបានទេ។"
          )
        )
      );
    } finally {
      setUploadingImage(false);
      event.target.value = "";
    }
  };

  const saveImage = async (event) => {
    event.preventDefault();

    if (!imageForm.image) {
      toast.error(
        tr(
          "charity.imageRequired",
          "Please upload an image.",
          "សូម Upload រូបភាព។"
        )
      );
      return;
    }

    const currentTitleField = `title_${suffix}`;

    if (!String(imageForm[currentTitleField] || "").trim()) {
      toast.error(
        isKhmer
          ? "សូមបញ្ចូលចំណងជើងរូបភាពជាភាសាខ្មែរ។"
          : "Please enter the image title in English."
      );
      return;
    }

    try {
      setSavingImage(true);

      const payload = {
        title_en: imageForm.title_en.trim() || null,
        title_km: imageForm.title_km.trim() || null,
        description_en: imageForm.description_en.trim() || null,
        description_km: imageForm.description_km.trim() || null,
        image: imageForm.image,
        order: Number(imageForm.order) || 0,
        is_active: Boolean(imageForm.is_active),
      };

      if (editingImageId) {
        await api.put(
          `/api/charity/images/${editingImageId}`,
          payload
        );

        toast.success(
          tr(
            "charity.imageUpdated",
            "Charity image updated successfully.",
            "បានកែប្រែរូបភាពសប្បុរសធម៌ដោយជោគជ័យ។"
          )
        );
      } else {
        await api.post("/api/charity/images", payload);

        toast.success(
          tr(
            "charity.imageCreated",
            "Charity image added successfully.",
            "បានបន្ថែមរូបភាពសប្បុរសធម៌ដោយជោគជ័យ។"
          )
        );
      }

      resetImageForm();
      await fetchImages();
    } catch (error) {
      console.error("Save charity image error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.imageSaveFailed",
            "Failed to save charity image.",
            "មិនអាចរក្សាទុករូបភាពសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setSavingImage(false);
    }
  };

  const deleteImage = async (item) => {
    const name =
      localized(item, "title") ||
      item.title_en ||
      item.title_km ||
      tr("charity.image", "this image", "រូបភាពនេះ");

    const confirmed = window.confirm(
      isKhmer
        ? `តើអ្នកប្រាកដថាចង់លុប "${name}" មែនទេ?`
        : `Delete "${name}"?`
    );

    if (!confirmed) return;

    try {
      setDeletingId(item.id);

      await api.delete(`/api/charity/images/${item.id}`);

      toast.success(
        tr(
          "charity.imageDeleted",
          "Charity image deleted successfully.",
          "បានលុបរូបភាពសប្បុរសធម៌ដោយជោគជ័យ។"
        )
      );

      await fetchImages();
    } catch (error) {
      console.error("Delete charity image error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.imageDeleteFailed",
            "Failed to delete charity image.",
            "មិនអាចលុបរូបភាពសប្បុរសធម៌បានទេ។"
          )
        )
      );
    } finally {
      setDeletingId(null);
    }
  };

  const toggleImageStatus = async (item) => {
    try {
      const payload = {
        is_active: !item.is_active,
      };

      await api.put(`/api/charity/images/${item.id}`, payload);

      setImages((current) =>
        current.map((record) =>
          record.id === item.id
            ? {
                ...record,
                ...payload,
              }
            : record
        )
      );
    } catch (error) {
      console.error("Update charity image status error:", error);

      toast.error(
        apiError(
          error,
          tr(
            "charity.statusFailed",
            "Failed to update status.",
            "មិនអាចធ្វើបច្ចុប្បន្នភាពស្ថានភាពបានទេ។"
          )
        )
      );
    }
  };


  if (loadingImages) {
    return (
      <div className="flex min-h-[60vh] items-center justify-center">
        <div className="h-10 w-10 animate-spin rounded-full border-4 border-slate-200 border-t-blue-900" />
      </div>
    );
  }

  return (
    <main
      className={`min-h-screen bg-slate-50 px-4 py-6 md:px-6 lg:px-8 ${
        isKhmer ? "font-khmer" : "font-english"
      }`}
    >
      <div className="mx-auto w-full max-w-[1450px]">
        <section className="mb-6 overflow-hidden rounded-2xl bg-[#0B1849] text-white shadow-sm">
          <div className="relative px-5 py-6 md:px-8 md:py-8">
            <div className="pointer-events-none absolute -right-20 -top-24 h-64 w-64 rounded-full bg-red-600/10 blur-3xl" />
            <div className="pointer-events-none absolute -bottom-24 left-20 h-56 w-56 rounded-full bg-white/5 blur-3xl" />

            <div className="relative z-10 flex flex-col gap-5 md:flex-row md:items-center md:justify-between">
              <div>
                <div className="mb-2 flex items-center gap-2 text-red-400">
                  <span className="h-[2px] w-7 rounded-full bg-red-500" />
                  <span className="text-[11px] font-bold uppercase tracking-[0.18em]">
                    {tr(
                      "admin.panel",
                      "SC Academy Admin",
                      "ផ្ទាំងអ្នកគ្រប់គ្រង SC Academy"
                    )}
                  </span>
                </div>

                <h1 className="text-[28px] font-bold md:text-[36px]">
                  {tr(
                    "charity.title",
                    "Charity Management",
                    "គ្រប់គ្រងសកម្មភាពសប្បុរសធម៌"
                  )}
                </h1>

                <p className="mt-2 max-w-2xl text-[13px] leading-6 text-white/65">
                  {tr(
                    "charity.subtitle",
                    "Manage charity activity images shown on the public website.",
                    "គ្រប់គ្រងរូបភាពសកម្មភាពសប្បុរសធម៌ដែលបង្ហាញលើគេហទំព័រ។"
                  )}
                </p>
              </div>

              <div className="flex flex-wrap gap-3">
                <button
                  type="button"
                  onClick={fetchImages}
                  disabled={loadingImages || savingImage}
                  className="inline-flex h-11 items-center justify-center gap-2 rounded-lg border border-white/10 bg-white/10 px-5 text-[12px] font-bold text-white transition hover:bg-white/20 disabled:opacity-60"
                >
                  <FiRefreshCw
                    size={15}
                    className={loadingImages ? "animate-spin" : ""}
                  />
                  {tr("common.refresh", "Refresh", "ផ្ទុកឡើងវិញ")}
                </button>

                <button
                  type="button"
                  onClick={openCreateImage}
                  className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-red-600 px-5 text-[12px] font-bold text-white transition hover:bg-red-700"
                >
                  <FiPlus size={16} />
                  {tr(
                    "charity.addImage",
                    "Add Image",
                    "បន្ថែមរូបភាព"
                  )}
                </button>
              </div>
            </div>
          </div>
        </section>

        {showImageForm && (
          <section className="mb-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
            <div className="flex items-center justify-between border-b border-slate-200 px-5 py-4 md:px-6">
              <div>
                <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-red-600">
                  {tr(
                    "charity.imageForm",
                    "Charity Image Form",
                    "ទម្រង់រូបភាពសប្បុរសធម៌"
                  )}
                </p>

                <h2 className="mt-1 text-[19px] font-bold text-blue-950">
                  {editingImageId
                    ? tr(
                        "charity.editImage",
                        "Edit Image",
                        "កែប្រែរូបភាព"
                      )
                    : tr(
                        "charity.createImage",
                        "Add New Image",
                        "បន្ថែមរូបភាពថ្មី"
                      )}
                </h2>
              </div>

              <button
                type="button"
                onClick={resetImageForm}
                disabled={savingImage || uploadingImage}
                className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-slate-500 transition hover:border-red-500 hover:bg-red-50 hover:text-red-600"
              >
                <FiX size={17} />
              </button>
            </div>

            <form onSubmit={saveImage} className="p-5 md:p-6">
              <div className="grid grid-cols-1 gap-6 xl:grid-cols-[1fr_340px]">
                <div className="space-y-4">
                  <div className="grid grid-cols-1 gap-4 md:grid-cols-2">
                    <label>
                      <span className="mb-2 block text-[12px] font-bold text-blue-950">
                        {isKhmer ? "ចំណងជើង" : "Title"}
                        <span className="ml-1 text-red-600">*</span>
                      </span>

                      <input
                        type="text"
                        name={`title_${suffix}`}
                        value={imageForm[`title_${suffix}`] || ""}
                        onChange={handleImageFormChange}
                        placeholder={
                          isKhmer
                            ? "ឧ. សកម្មភាពចែកសម្ភារៈសិក្សា"
                            : "e.g. Learning Materials Donation"
                        }
                        className="h-11 w-full rounded-lg border border-slate-200 bg-slate-50 px-4 text-[13px] outline-none focus:border-blue-800 focus:bg-white"
                      />
                    </label>

                    <label>
                      <span className="mb-2 block text-[12px] font-bold text-blue-950">
                        {tr(
                          "charity.displayOrder",
                          "Display Order",
                          "លំដាប់បង្ហាញ"
                        )}
                      </span>

                      <input
                        type="number"
                        min="0"
                        name="order"
                        value={imageForm.order}
                        onChange={handleImageFormChange}
                        className="h-11 w-full rounded-lg border border-slate-200 bg-slate-50 px-4 text-[13px] outline-none focus:border-blue-800 focus:bg-white"
                      />
                    </label>
                  </div>

                  <label>
                    <span className="mb-2 block text-[12px] font-bold text-blue-950">
                      {isKhmer ? "ការពិពណ៌នា" : "Description"}
                    </span>

                    <textarea
                      name={`description_${suffix}`}
                      value={imageForm[`description_${suffix}`] || ""}
                      onChange={handleImageFormChange}
                      rows={5}
                      placeholder={
                        isKhmer
                          ? "សរសេរការពិពណ៌នាអំពីសកម្មភាព..."
                          : "Write a short activity description..."
                      }
                      className="w-full resize-y rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-[13px] outline-none focus:border-blue-800 focus:bg-white"
                    />
                  </label>

                  <label className="flex cursor-pointer items-center justify-between rounded-xl bg-slate-50 p-4">
                    <span className="text-[12px] font-bold text-slate-700">
                      {tr("common.active", "Active", "សកម្ម")}
                    </span>

                    <span className="relative inline-flex">
                      <input
                        type="checkbox"
                        name="is_active"
                        checked={imageForm.is_active}
                        onChange={handleImageFormChange}
                        className="peer sr-only"
                      />

                      <span className="h-6 w-11 rounded-full bg-slate-300 transition peer-checked:bg-blue-900" />
                      <span className="absolute left-1 top-1 h-4 w-4 rounded-full bg-white shadow-sm transition peer-checked:translate-x-5" />
                    </span>
                  </label>
                </div>

                <aside className="space-y-4">
                  <div className="overflow-hidden rounded-2xl border border-slate-200 bg-slate-100">
                    <div className="relative flex aspect-[4/3] items-center justify-center">
                      {imageForm.image ? (
                        <img
                          src={getImageUrl(imageForm.image)}
                          alt="Preview"
                          className="absolute inset-0 h-full w-full object-cover"
                        />
                      ) : (
                        <div className="flex flex-col items-center text-slate-400">
                          <FiImage size={36} />
                          <span className="mt-2 text-[11px] font-semibold">
                            {tr(
                              "charity.imagePreview",
                              "Image Preview",
                              "មើលរូបភាពជាមុន"
                            )}
                          </span>
                        </div>
                      )}

                      {uploadingImage && (
                        <div className="absolute inset-0 flex items-center justify-center bg-white/80">
                          <div className="text-center">
                            <span className="mx-auto block h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-900" />
                            <p className="mt-3 text-[11px] font-bold text-blue-950">
                              {tr(
                                "charity.uploading",
                                "Uploading...",
                                "កំពុង Upload..."
                              )}
                            </p>
                          </div>
                        </div>
                      )}
                    </div>
                  </div>

                  <label className="flex min-h-[110px] cursor-pointer flex-col items-center justify-center rounded-xl border-2 border-dashed border-slate-300 bg-slate-50 p-4 text-center transition hover:border-blue-800 hover:bg-blue-50">
                    <FiUploadCloud size={27} className="text-blue-900" />

                    <span className="mt-2 text-[12px] font-bold text-blue-950">
                      {imageForm.image
                        ? tr(
                            "charity.replaceImage",
                            "Replace Image",
                            "ប្ដូររូបភាព"
                          )
                        : tr(
                            "charity.uploadImage",
                            "Upload Image",
                            "Upload រូបភាព"
                          )}
                    </span>

                    <span className="mt-1 text-[10px] text-slate-500">
                      JPG, PNG, WEBP — Max 5MB
                    </span>

                    <input
                      type="file"
                      accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp"
                      onChange={uploadImageFile}
                      disabled={uploadingImage}
                      className="hidden"
                    />
                  </label>
                </aside>
              </div>

              <div className="mt-6 flex flex-col-reverse gap-3 border-t border-slate-200 pt-5 sm:flex-row sm:justify-end">
                <button
                  type="button"
                  onClick={resetImageForm}
                  disabled={savingImage || uploadingImage}
                  className="inline-flex h-11 items-center justify-center rounded-lg border border-slate-200 px-6 text-[12px] font-bold text-slate-700 hover:bg-slate-50"
                >
                  {tr("common.cancel", "Cancel", "បោះបង់")}
                </button>

                <button
                  type="submit"
                  disabled={savingImage || uploadingImage}
                  className="inline-flex h-11 items-center justify-center gap-2 rounded-lg bg-red-600 px-7 text-[12px] font-bold text-white transition hover:bg-red-700 disabled:opacity-60"
                >
                  {savingImage ? (
                    <>
                      <span className="h-4 w-4 animate-spin rounded-full border-2 border-white/30 border-t-white" />
                      {tr(
                        "common.saving",
                        "Saving...",
                        "កំពុងរក្សាទុក..."
                      )}
                    </>
                  ) : (
                    <>
                      <FiCheck size={15} />
                      {editingImageId
                        ? tr(
                            "common.update",
                            "Update",
                            "ធ្វើបច្ចុប្បន្នភាព"
                          )
                        : tr(
                            "common.create",
                            "Create",
                            "បង្កើត"
                          )}
                    </>
                  )}
                </button>
              </div>
            </form>
          </section>
        )}

        <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="flex flex-col gap-4 border-b border-slate-200 px-5 py-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <p className="text-[10px] font-bold uppercase tracking-[0.15em] text-red-600">
                {tr(
                  "charity.imageLibrary",
                  "Charity Image Library",
                  "បណ្ណាល័យរូបភាពសប្បុរសធម៌"
                )}
              </p>

              <h2 className="mt-1 text-[18px] font-bold text-blue-950">
                {tr(
                  "charity.images",
                  "Charity Images",
                  "រូបភាពសប្បុរសធម៌"
                )}
              </h2>
            </div>

            <div className="relative w-full sm:w-[300px]">
              <FiSearch
                size={15}
                className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400"
              />
              <input
                type="search"
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder={tr(
                  "charity.searchImages",
                  "Search images...",
                  "ស្វែងរករូបភាព..."
                )}
                className="h-10 w-full rounded-lg border border-slate-200 bg-slate-50 pl-9 pr-3 text-[12px] outline-none focus:border-blue-800 focus:bg-white"
              />
            </div>
          </div>

          {loadingImages ? (
            <div className="flex min-h-[240px] items-center justify-center">
              <div className="h-8 w-8 animate-spin rounded-full border-4 border-slate-200 border-t-blue-900" />
            </div>
          ) : filteredImages.length === 0 ? (
            <div className="flex min-h-[260px] flex-col items-center justify-center px-5 text-center">
              <div className="flex h-14 w-14 items-center justify-center rounded-2xl bg-blue-50 text-blue-900">
                <FiImage size={26} />
              </div>

              <h3 className="mt-4 text-[17px] font-bold text-blue-950">
                {tr(
                  "charity.noImages",
                  "No Charity Images",
                  "មិនទាន់មានរូបភាពសប្បុរសធម៌"
                )}
              </h3>

              <button
                type="button"
                onClick={openCreateImage}
                className="mt-5 inline-flex h-10 items-center gap-2 rounded-lg bg-red-600 px-5 text-[11px] font-bold text-white hover:bg-red-700"
              >
                <FiPlus size={14} />
                {tr(
                  "charity.addImage",
                  "Add Image",
                  "បន្ថែមរូបភាព"
                )}
              </button>
            </div>
          ) : (
            <>
              <div className="hidden overflow-x-auto lg:block">
                <table className="w-full min-w-[900px] border-collapse">
                  <thead>
                    <tr className="bg-slate-50 text-left">
                      {[
                        tr("common.image", "Image", "រូបភាព"),
                        tr("common.title", "Title", "ចំណងជើង"),
                        tr(
                          "common.description",
                          "Description",
                          "ការពិពណ៌នា"
                        ),
                        tr("common.order", "Order", "លំដាប់"),
                        tr("common.status", "Status", "ស្ថានភាព"),
                        tr("common.actions", "Actions", "សកម្មភាព"),
                      ].map((heading) => (
                        <th
                          key={heading}
                          className="border-b border-slate-200 px-4 py-3 text-[10px] font-bold uppercase tracking-[0.1em] text-slate-500"
                        >
                          {heading}
                        </th>
                      ))}
                    </tr>
                  </thead>

                  <tbody>
                    {filteredImages.map((item) => (
                      <tr
                        key={item.id}
                        className="border-b border-slate-100 last:border-b-0 hover:bg-slate-50/70"
                      >
                        <td className="px-4 py-4">
                          <div className="h-16 w-24 overflow-hidden rounded-lg bg-slate-100">
                            <img
                              src={getImageUrl(item.image)}
                              alt={localized(item, "title", "Charity")}
                              className="h-full w-full object-cover"
                            />
                          </div>
                        </td>

                        <td className="px-4 py-4">
                          <p className="max-w-[220px] truncate text-[13px] font-bold text-blue-950">
                            {localized(item, "title", "—")}
                          </p>
                        </td>

                        <td className="px-4 py-4">
                          <p className="max-w-[320px] line-clamp-2 text-[11px] leading-5 text-slate-500">
                            {localized(item, "description", "—")}
                          </p>
                        </td>

                        <td className="px-4 py-4 text-[12px] font-semibold text-slate-700">
                          {item.order ?? 0}
                        </td>

                        <td className="px-4 py-4">
                          <button
                            type="button"
                            onClick={() => toggleImageStatus(item)}
                            className={`inline-flex h-8 items-center rounded-full px-3 text-[10px] font-bold ${
                              item.is_active
                                ? "bg-emerald-100 text-emerald-700"
                                : "bg-red-100 text-red-700"
                            }`}
                          >
                            {item.is_active
                              ? tr("common.active", "Active", "សកម្ម")
                              : tr(
                                  "common.inactive",
                                  "Inactive",
                                  "អសកម្ម"
                                )}
                          </button>
                        </td>

                        <td className="px-4 py-4">
                          <div className="flex items-center gap-2">
                            <button
                              type="button"
                              onClick={() => openEditImage(item)}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-blue-900 hover:border-blue-900 hover:bg-blue-50"
                            >
                              <FiEdit2 size={14} />
                            </button>

                            <button
                              type="button"
                              onClick={() => deleteImage(item)}
                              disabled={deletingId === item.id}
                              className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 hover:bg-red-600 hover:text-white disabled:opacity-60"
                            >
                              {deletingId === item.id ? (
                                <span className="h-4 w-4 animate-spin rounded-full border-2 border-red-300 border-t-red-600" />
                              ) : (
                                <FiTrash2 size={14} />
                              )}
                            </button>
                          </div>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>

              <div className="grid grid-cols-1 gap-4 p-4 sm:grid-cols-2 lg:hidden">
                {filteredImages.map((item) => (
                  <article
                    key={item.id}
                    className="overflow-hidden rounded-2xl border border-slate-200 bg-white"
                  >
                    <div className="h-[210px] bg-slate-100">
                      <img
                        src={getImageUrl(item.image)}
                        alt={localized(item, "title", "Charity")}
                        className="h-full w-full object-cover"
                      />
                    </div>

                    <div className="p-4">
                      <h3 className="text-[15px] font-bold text-blue-950">
                        {localized(item, "title", "—")}
                      </h3>

                      <p className="mt-2 line-clamp-3 text-[11px] leading-5 text-slate-500">
                        {localized(item, "description", "—")}
                      </p>

                      <div className="mt-4 flex items-center justify-between border-t border-slate-200 pt-4">
                        <button
                          type="button"
                          onClick={() => toggleImageStatus(item)}
                          className={`rounded-full px-3 py-1 text-[10px] font-bold ${
                            item.is_active
                              ? "bg-emerald-100 text-emerald-700"
                              : "bg-red-100 text-red-700"
                          }`}
                        >
                          {item.is_active
                            ? tr("common.active", "Active", "សកម្ម")
                            : tr(
                                "common.inactive",
                                "Inactive",
                                "អសកម្ម"
                              )}
                        </button>

                        <div className="flex gap-2">
                          <button
                            type="button"
                            onClick={() => openEditImage(item)}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-slate-200 text-blue-900"
                          >
                            <FiEdit2 size={14} />
                          </button>

                          <button
                            type="button"
                            onClick={() => deleteImage(item)}
                            disabled={deletingId === item.id}
                            className="flex h-9 w-9 items-center justify-center rounded-lg border border-red-200 bg-red-50 text-red-600 disabled:opacity-60"
                          >
                            <FiTrash2 size={14} />
                          </button>
                        </div>
                      </div>
                    </div>
                  </article>
                ))}
              </div>
            </>
          )}
        </section>
      </div>
    </main>
  );
};

export default AdminCharity;
